/*
 * ОБЩЕЕ ОПИСАНИЕ ПРОГРАММЫ
 * ------------------------
 * Микроконтроллер STM32F407 работает от внутреннего генератора HSI (16 МГц).
 * Программа:
 *   1) настраивает системный таймер SysTick на прерывание раз в 1 мс;
 *   2) настраивает 4 кнопки (PB11..PB14) как входы и 4 светодиода (PB5..PB8)
 *      как выходы;
 *   3) настраивает USART2 (PA2 = TX, PA3 = RX) на скорость 57600 бод, 8N1;
 *   4) отправляет в терминал строку "abcde";
 *   5) в бесконечном цикле опрашивает кнопки и в зависимости от нажатой
 *      кнопки переключает режим работы (mode = 1..4) и зажигает
 *      соответствующий светодиод:
 *        режим 1 – эхо: что получили, то сразу отправили обратно;
 *        режим 2 – запоминаем последний принятый символ и непрерывно
 *                  отправляем его снова и снова;
 *        режим 3 – после приёма символа непрерывно отправляем его и
 *                  каждый раз увеличиваем код на 1 (перебор ASCII 32..126);
 *        режим 4 – на каждый принятый символ отправляем его код в
 *                  десятичном виде (например, "97\r\n" для буквы 'a').
 */

// Подключаем стандартные целочисленные типы фиксированного размера
// (uint8_t – 8 бит без знака, uint32_t – 32 бита без знака и т.д.).
#include <stdint.h>

// Пустая строка – просто визуальный разделитель между блоками #include.

// Подключаем заголовочный файл с описанием регистров STM32F407:
// именно он даёт нам имена RCC, GPIOA, GPIOB, USART2, PWR и все битовые маски
// вида RCC_AHB1ENR_GPIOBEN, USART_SR_TXE и т.п.
#include "stm32f407xx.h"
// Подключаем стандартный ввод-вывод. Нужен здесь только ради функции sprintf(),
// которая используется в режиме 4 для превращения числа в текст.
#include <stdio.h>

// Объявляем, что переменная systemTimeCounter определена в ДРУГОМ файле
// (обычно в обработчике SysTick_Handler, который раз в 1 мс делает
// systemTimeCounter++). Слово extern говорит компилятору: «память под неё
// выделена не здесь, просто знай, что она есть». Это счётчик миллисекунд.
// ВНИМАНИЕ: правильнее объявлять её как "extern volatile uint32_t", иначе
// компилятор при оптимизации может решить, что значение не меняется, и
// зациклить delayMs навсегда.
extern uint32_t systemTimeCounter;


// Функция задержки в миллисекундах. Принимает число мс, которое нужно ждать.
// (В этой программе она нигде реально не вызывается – все вызовы закомментированы.)
void delayMs(uint32_t delay)
{	// Открывающая фигурная скобка – начало тела функции delayMs.
	// Запоминаем текущее значение счётчика миллисекунд как «момент старта».
	uint32_t curr = systemTimeCounter;
	// Цикл ожидания: пока разница «текущее время минус время старта» меньше
	// заданной задержки – крутимся в цикле. Вычитание беззнаковых чисел
	// корректно работает даже при переполнении счётчика (через ~49 суток).
	while(systemTimeCounter - curr < delay)
	// Начало тела цикла while.
	{	}
	// Тело цикла пустое: мы просто ждём, пока SysTick в прерывании увеличит счётчик.
	// Закрывающая скобка тела цикла выше.
}	// Конец функции delayMs.



// Главная функция программы – отсюда начинается выполнение после старта и
// инициализации системы. Возвращаемое значение int по традиции, но из main
// в микроконтроллере мы никогда не выходим (внутри бесконечный цикл).
int main(void)
{	// Начало тела функции main.
	// PWR AND SYS ENABLE
	// Включаем тактирование блока SYSCFG (конфигурация системы: ремап памяти,
	// внешние прерывания и т.п.). Бит SYSCFGEN лежит в регистре APB2ENR шины APB2.
	// Оператор |= ставит нужный бит в 1, не трогая остальные биты регистра.
	RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;
	// Включаем тактирование блока управления питанием PWR (шина APB1).
	RCC->APB1ENR |= RCC_APB1ENR_PWREN;
	// Пытаемся записать бит VOSRDY в регистр состояния PWR->CSR. На самом деле
	// это флаг ТОЛЬКО ДЛЯ ЧТЕНИЯ («регулятор напряжения готов»), его выставляет
	// само железо, поэтому эта запись ни на что не влияет. Строку можно убрать.
	PWR->CSR |= PWR_CSR_VOSRDY;

	// Настраиваем системный таймер SysTick: 16 000 000 / 1000 = 16 000 тактов.
	// При частоте ядра 16 МГц это ровно 1 мс. Функция сама загружает значение
	// в регистр перезагрузки, запускает таймер и включает его прерывание.
	SysTick_Config(16000000/1000);
	// Ставим прерыванию SysTick приоритет 0 – самый высокий в системе, чтобы
	// отсчёт времени не пропускался из-за других прерываний.
	NVIC_SetPriority(SysTick_IRQn,0);
	// Разрешаем прерывание SysTick в контроллере прерываний NVIC. Для SysTick это
	// по сути лишнее (SysTick_Config уже всё включила), но вреда не приносит.
	NVIC_EnableIRQ(SysTick_IRQn);

	// switches
		// Включаем тактирование порта GPIOB (на нём и кнопки, и светодиоды).
		// Пока порт не тактируется, его регистры не работают.
		RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;
		// Настраиваем PB11 и PB12 как ВХОДЫ. В регистре MODER на каждый вывод отведено
		// 2 бита: 00 – вход, 01 – выход, 10 – альтернативная функция, 11 – аналоговый.
		// (3 << MODE11_Pos) – маска из двух единиц на позициях вывода 11;
		// ~ инвертирует её, &= обнуляет эти два бита => режим «вход».
		GPIOB->MODER &= ~((3 << GPIO_MODER_MODE11_Pos)|(3 << GPIO_MODER_MODE12_Pos)); ///F ?
		// То же самое для PB13 и PB14: делаем их входами (кнопки).
		// Подтяжка (PUPDR) не включалась, значит подтягивающие резисторы
		// должны стоять на самой плате.
		GPIOB->MODER &= ~((3 << GPIO_MODER_MODE13_Pos)|(3 << GPIO_MODER_MODE14_Pos));

		//LEDs
		//RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;// | RCC_AHB1ENR_GPIOEN;
		// Сначала обнуляем два бита режима у PB5 и PB6 (сброс в состояние «вход»),
		// чтобы затем гарантированно записать нужное значение.
		GPIOB->MODER &= ~((3 << GPIO_MODER_MODE5_Pos)|(3 << GPIO_MODER_MODE6_Pos));
		// То же для PB7 и PB8.
		GPIOB->MODER &= ~((3 << GPIO_MODER_MODE7_Pos)|(3 << GPIO_MODER_MODE8_Pos));

		// Записываем 01 (режим «выход общего назначения») для PB5 и PB6.
		// Тип выхода по умолчанию – push-pull, скорость – низкая; для светодиодов хватает.
		GPIOB->MODER |= ((1 << GPIO_MODER_MODE5_Pos)|(1 << GPIO_MODER_MODE6_Pos));
		// То же для PB7 и PB8 – теперь все четыре вывода PB5..PB8 это выходы (светодиоды).
		GPIOB->MODER |= ((1 << GPIO_MODER_MODE7_Pos)|(1 << GPIO_MODER_MODE8_Pos));
		// Замечание: после сброса ODR = 0, значит на всех светодиодах сейчас низкий
		// уровень, т.е. при активном нуле они все горят, пока не нажата первая кнопка.

		// USART
		// Включаем тактирование порта GPIOA: на нём выводы PA2 (TX) и PA3 (RX) USART2.
		RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
		// Обнуляем биты режима для PA2 и PA3 (подготовка к записи нового режима).
		GPIOA->MODER &= ~((3 << GPIO_MODER_MODE2_Pos)| (3 <<GPIO_MODER_MODE3_Pos ));
		// Записываем 10 (двоичное) = 2, то есть режим «альтернативная функция»:
		// выводом теперь управляет не порт GPIO, а периферия (USART2).
		GPIOA->MODER |= (2 << GPIO_MODER_MODE2_Pos)| (2 <<GPIO_MODER_MODE3_Pos );
		// Ставим для PA2 и PA3 максимальную скорость фронтов (биты 11 = very high).
		// Маски OSPEEDR2/OSPEEDR3 уже двухбитные, поэтому сдвигать ничего не нужно.
		GPIOA->OSPEEDR |=  GPIO_OSPEEDER_OSPEEDR2 | GPIO_OSPEEDER_OSPEEDR3;
		// Выбираем номер альтернативной функции AF7 для PA2 и PA3. В таблице
		// микроконтроллера AF7 на этих выводах = USART2. AFR[0] (AFRL) управляет
		// выводами 0..7, на каждый вывод по 4 бита.
		GPIOA->AFR[0] |= (7 << GPIO_AFRL_AFSEL2_Pos) | (7 << GPIO_AFRL_AFSEL3_Pos);

		// Включаем тактирование самого модуля USART2 (он сидит на шине APB1).
		RCC->APB1ENR |= RCC_APB1ENR_USART2EN;



		// Сбрасываем бит M: длина слова 8 бит данных (а не 9).
		USART2->CR1 &= ~(USART_CR1_M);
		//USART2->CR1 |= USART_CR1_OVER8; //na 16 chastey delim i berem seredinu
		// Задаём скорость через регистр BRR. Формула: USARTDIV = fck / (16 * baud) =
		// 16 000 000 / (16 * 57 600) ≈ 17,36. Целая часть 17 = 0x11 идёт в старшие
		// биты (мантисса), дробная часть 0,36 * 16 ≈ 5,76 ≈ 6 = 0x6 идёт в младшие
		// 4 бита. Итого 0x116. Скорость получается ~57 600 бод (ошибка менее 0,1 %).
		USART2->BRR |= 0X116; //57 600 skorost' //17.36; 17D = 11H
		// Обнуляем поле STOP в CR2: один стоп-бит.
		USART2->CR2 &= ~(USART_CR2_STOP); //0,36*16=5,76 -> 6D = 6H
		// Включаем сам модуль USART (бит UE – USART Enable).
		USART2->CR1 |= USART_CR1_UE;
		// Включаем передатчик (TE) и приёмник (RE). Чётность не включена (PCE = 0),
		// значит формат кадра 8N1: 8 бит, без чётности, 1 стоп-бит.
		USART2->CR1 |= USART_CR1_TE | USART_CR1_RE;

		// Создаём массив из символов: 'a','b','c','d','e' и завершающий '\0'
		// (размер массива 6 байт). Эту строку отправим один раз при старте.
		char str[] = "abcde";
		// Цикл по символам строки: i – индекс, условие str[i] истинно, пока символ
		// не равен '\0' (конец строки); после каждого шага i увеличивается на 1.
		for(int i =0; str[i];i++)
		{	// Начало тела цикла for.
			// Ждём, пока в регистре статуса SR появится флаг TXE (Transmit data
			// register Empty) – передающий регистр пуст, можно писать следующий байт.
			// Пока флаг = 0, условие !(...) истинно и мы крутимся на месте.
			while(!(USART2->SR & USART_SR_TXE));
			// Записываем очередной символ в регистр данных DR – с этого момента
			// USART начинает побитово отправлять его на линию TX.
			USART2->DR = str[i];
		}	// Конец тела цикла for – переходим к следующему символу.

// Переменная режима работы: 1..4 – номер последней нажатой кнопки.
// ВНИМАНИЕ: она не инициализирована, поэтому до первого нажатия содержит
// «мусор». Лучше писать uint8_t mode = 0;
uint8_t mode;
// Переменная для хранения последнего принятого (или формируемого) символа.
// Тоже не инициализирована; лучше char symbol = 0;
char symbol;
  // Бесконечный цикл: основная работа программы. Микроконтроллер из него не выходит.
  while (1)
  {	// Начало тела бесконечного цикла.
	  // Проверяем кнопку на PB11. Читаем входной регистр IDR и выделяем бит ID11.
	  // Кнопка при нажатии подтягивает вывод к земле (уровень 0), поэтому условие
	  // !(...) означает «кнопка нажата».
	  if(!(GPIOB->IDR & GPIO_IDR_ID11))
	  {	// Начало блока: действия при нажатии кнопки 1.
		  // Запоминаем, что выбран режим 1 (эхо).
		  mode = 1;
		  // Сбрасываем бит 5 в регистре выходных данных: на PB5 низкий уровень =>
		  // светодиод 1 ГОРИТ.
		  GPIOB->ODR &= ~GPIO_ODR_OD5; //LED on
		  // Ставим бит 6 в 1: на PB6 высокий уровень => светодиод 2 погашен.
		  GPIOB->ODR |= GPIO_ODR_OD6;
		  // Гасим светодиод 3 (PB7 = 1).
		  GPIOB->ODR |= GPIO_ODR_OD7;
		  // Гасим светодиод 4 (PB8 = 1).
		  GPIOB->ODR |= GPIO_ODR_OD8;//LED off
	  }	// Конец блока кнопки 1.

	  // Проверяем кнопку на PB12 (кнопка 2), тоже активный ноль.
	  if(!(GPIOB->IDR & GPIO_IDR_ID12))
	  	  {	// Начало блока: действия при нажатии кнопки 2.
	  		  // Выбран режим 2 (повтор последнего символа).
	  		  mode = 2;
	  		  // Зажигаем светодиод 2 (PB6 = 0).
	  		  GPIOB->ODR &= ~GPIO_ODR_OD6; //LED on
	  		  // Гасим светодиод 1 (PB5 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD5;
	  		  // Гасим светодиод 3 (PB7 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD7;
	  		  // Гасим светодиод 4 (PB8 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD8;//LED off
	  		  // Обнуляем запомненный символ. Пока кнопка удерживается, эта строка
	  		  // выполняется на каждом проходе цикла, поэтому символ остаётся 0
	  		  // и ничего не отправляется; отправка начнётся после отпускания кнопки
	  		  // и приёма нового символа.
	  		  symbol = 0;
	  	  }	// Конец блока кнопки 2.
	  // Проверяем кнопку на PB13 (кнопка 3).
	  if(!(GPIOB->IDR & GPIO_IDR_ID13))
	  	  {	// Начало блока: действия при нажатии кнопки 3.
	  		  // Выбран режим 3 (перебор ASCII-символов).
	  		  mode = 3;
	  		  // Зажигаем светодиод 3 (PB7 = 0).
	  		  GPIOB->ODR &= ~GPIO_ODR_OD7; //LED on
	  		  // Гасим светодиод 2 (PB6 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD6;
	  		  // Гасим светодиод 1 (PB5 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD5;
	  		  // Гасим светодиод 4 (PB8 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD8;//LED off
	  		  // Обнуляем символ – так же, как в режиме 2: ждём нового символа с терминала.
	  		  symbol = 0;
	  	  }	// Конец блока кнопки 3.
	  // Проверяем кнопку на PB14 (кнопка 4).
	  if(!(GPIOB->IDR & GPIO_IDR_ID14))
	  	  {	// Начало блока: действия при нажатии кнопки 4.
	  		  // Выбран режим 4 (вывод кода символа числом).
	  		  mode = 4;
	  		  // Зажигаем светодиод 4 (PB8 = 0).
	  		  GPIOB->ODR &= ~GPIO_ODR_OD8; //LED on
	  		  // Гасим светодиод 2 (PB6 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD6;
	  		  // Гасим светодиод 3 (PB7 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD7;
	  		  // Гасим светодиод 1 (PB5 = 1).
	  		  GPIOB->ODR |= GPIO_ODR_OD5;//LED off
	  	  }	// Конец блока кнопки 4.

	  // ---------- РЕЖИМ 1: ЭХО ----------
	  // Если сейчас выбран режим 1...
	  if(mode ==1)
	  {	// Начало блока режима 1.
		  // Проверяем флаг RXNE (Receive data register Not Empty): он равен 1, когда
		  // USART принял байт и тот лежит в DR, ожидая чтения.
		  if (USART2->SR & USART_SR_RXNE)
		  {	// Начало блока: байт получен.
			  // Читаем принятый байт из DR. Само чтение сбрасывает флаг RXNE.
			  symbol = USART2->DR;
			  // Ждём, пока передатчик освободится (флаг TXE).
			  while(!(USART2->SR & USART_SR_TXE));
			  // Отправляем тот же байт обратно – получается «эхо».
			  USART2->DR = symbol;
		  }	// Конец блока «байт получен».
	  }	// Конец блока режима 1.

	  // ---------- РЕЖИМ 2: ПОВТОР ПОСЛЕДНЕГО СИМВОЛА ----------
	  // Если выбран режим 2...
	  if(mode == 2)
	  	  {	// Начало блока режима 2.
	  		  // Если пришёл новый байт...
	  		  if (USART2->SR & USART_SR_RXNE)
	  		  {	// Начало блока «пришёл байт».
	  			  // ...запоминаем его в symbol (флаг RXNE сбросится сам при чтении DR).
	  			  symbol = USART2->DR;
	  		  }	// Конец блока «пришёл байт».
	  		  // Если в symbol есть что-то отличное от нуля (то есть мы уже получили
	  		  // символ после нажатия кнопки)...
	  		  if ((symbol != 0)){
	  			  // ...ждём готовности передатчика...
	  			  while(!(USART2->SR & USART_SR_TXE));
	  			  // ...и отправляем запомненный символ. Так как это происходит на
	  			  // каждом проходе цикла, символ уходит в терминал непрерывным потоком.
	  			  USART2->DR = symbol;
	  			  // Здесь можно включить паузу 100 мс, чтобы поток был не таким плотным.
	  			  //delayMs(100);

	  		  }	// Конец блока «символ не ноль».
	  	  }	// Конец блока режима 2.

	  // ---------- РЕЖИМ 3: ПЕРЕБОР СИМВОЛОВ ----------
	  // Если выбран режим 3...
	  if(mode ==3)
	  {	// Начало блока режима 3.
		  // Если принят байт...
		  if (USART2->SR & USART_SR_RXNE)
		  {	// Начало блока «принят байт».
			  // ...сохраняем его как стартовый символ для перебора.
			  symbol = USART2->DR;
		  }	// Конец блока «принят байт».
		  // Если стартовый символ уже есть (не 0)...
		  if ((symbol !=0)){
			  // ...ждём готовности передатчика...
			  while(!(USART2->SR & USART_SR_TXE));
			  // ...отправляем текущий символ...
			  USART2->DR = symbol;
			  // ...и увеличиваем его код на 1: следующим уйдёт следующий символ
			  // по таблице ASCII (a -> b -> c ...).
			  symbol++;
			  // Если вышли за границы печатных символов (код больше 126 '~' или
			  // меньше 32 – пробел)...
			  if (symbol > 126 || symbol < 32){
				  // ...возвращаемся к пробелу (код 32) – перебор идёт по кругу.
				  symbol = 32;
				  // Паузу, если включить её здесь, получится только в момент
				  // «закольцовки», а не после каждого символа.
				  //delayMs(100);
			  }	// Конец блока «выход за границы».
		  }	// Конец блока «символ не ноль».
	  }	// Конец блока режима 3.

	  // ---------- РЕЖИМ 4: ВЫВОД КОДА СИМВОЛА ЧИСЛОМ ----------
	  // Если выбран режим 4...
	  if(mode ==4)
	  	  {	// Начало блока режима 4.
	  		  // Если принят байт...
	  		  if (USART2->SR & USART_SR_RXNE)
	  		  {	// Начало блока «принят байт».
	  			  // ...читаем его в symbol.
	  			  symbol = USART2->DR;
	  			  // Локальный буфер на 16 символов под текстовую запись числа.
	  			  char buf[16];
	  			  // Превращаем код символа в строку: "%d" – целое десятичное число,
	  			  // "\r\n" – возврат каретки и перевод строки (чтобы каждое число
	  			  // было в новой строке терминала). Например, для 'a' получится "97\r\n".
	  			  sprintf(buf, "%d\r\n", symbol);
	  			  // Цикл по строке buf до символа конца строки '\0'.
	  			  for (int i = 0; buf[i] != '\0'; i++){
	  				  // Ждём готовности передатчика.
	  				  while(!(USART2->SR & USART_SR_TXE));
	  				  // Отправляем очередной символ строки.
	  				  USART2->DR = buf[i];
	  			  }	// Конец цикла отправки строки.
	  		  }	// Конец блока «принят байт».
	  	  }	// Конец блока режима 4.







	  // Пауза 1 секунда между итерациями цикла (отключена, поэтому цикл крутится
	  // на максимальной скорости).
	  //delayMs(1000);


  }	// Конец бесконечного цикла while(1).

}	// Конец функции main (до этой строки выполнение никогда не доходит).